from pathlib import Path
import re,json
P=Path('/private/tmp/kuch13round/student'); D=Path('docs/reaudit-2026-11-16/ch13/student')
def build(lesson,solutions,questions):
 if (D/(lesson+'.input.jsonl')).exists(): return
 text=(P/(lesson+'.md')).read_text(); rows=[]
 for task,body,expected in solutions:
  sec=text.split('## task: '+task+' |',1)[1].split('## task:',1)[0]
  starter=re.search(r'### Заготовка\s*```python\n(.*?)```',sec,re.S)
  code=(starter.group(1) if starter else '')
  if '...' in code:
   # function placeholder must be replaced with the independently written implementation
   code=code.replace('    ...','    pass')
  code+='\n'+body
  rows.append(dict(lesson=lesson,task=task,code=code,expect=expected,Q1='Получить '+expected,Q2='Выполнить код по публичному условию «'+sec.splitlines()[0].strip()+'» и разобранным выше примерам.',Q3=expected))
 for q,choice,expected in questions:
  rows.append(dict(question=lesson+'/'+q,choice=choice,expect=expected,Q1='Ответить на вопрос '+q,Q2='Выбрать вариант из опубликованных вариантов; опора — теория урока.',Q3=expected))
 (D/(lesson+'.input.jsonl')).write_text(''.join(json.dumps(r,ensure_ascii=False)+'\n' for r in rows))

