('parse-llm','TOPICS={"кофе","еда","обслуживание","доставка","цена","атмосфера"}\ndef parse(answer):\n    try:\n        d=json.loads(answer[answer.index("{"):answer.rindex("}")+1])\n        if isinstance(d,dict) and d.get("sentiment") in ["positive","negative"] and d.get("topic") in TOPICS:\n            return {"sentiment":d["sentiment"],"topic":d["topic"],"ok":True}\n    except (ValueError,TypeError,AttributeError):\n        pass\n    return {"sentiment":None,"topic":None,"ok":False}\nparsed=pd.DataFrame([parse(a) for a in raw])\nn_bad=int((~parsed.ok).sum())','parsed8×3,невалидные два None и False,пустой негоден'),
