('models','import numpy as np\nfrom sklearn.metrics import f1_score\nfrom sklearn.model_selection import GroupShuffleSplit\nlabels=sorted(r.topic.unique())\nrows={k:{} for k in ["повторы","новые","без пересечения"]}\nfor target,name in [(y,"sent"),(r.topic,"topic")]:\n    a,b=train_test_split(r.index,test_size=.25,random_state=42,stratify=target)\n    m=new_model().fit(r.loc[a,"text"],target.loc[a]);pred=m.predict(r.loc[b,"text"])\n    if name=="sent": acc_sent=round(accuracy_score(target.loc[b],pred),3)\n    else: acc_topic=round(accuracy_score(target.loc[b],pred),3)\n    repeated=r.loc[b,"text"].isin(r.loc[a,"text"]).to_numpy()\n    for key,mask in [("повторы",repeated),("новые",~repeated)]:\n        rows[key]["n_"+name]=int(mask.sum())\n        rows[key]["acc_"+name]=round(accuracy_score(target.loc[b].to_numpy()[mask],pred[mask]),3)\n        if name=="topic": rows[key]["macro_f1_topic"]=round(f1_score(target.loc[b].to_numpy()[mask],pred[mask],labels=labels,average="macro",zero_division=0),3)\na,b=next(GroupShuffleSplit(n_splits=1,test_size=.25,random_state=42).split(r,groups=r.text))\ngroup_test_ids=r.iloc[b].review_id.tolist()\nfor target,name in [(y,"sent"),(r.topic,"topic")]:\n    m=new_model().fit(r.iloc[a].text,target.iloc[a]);pred=m.predict(r.iloc[b].text)\n    rows["без пересечения"]["n_"+name]=len(b)\n    rows["без пересечения"]["acc_"+name]=round(accuracy_score(target.iloc[b],pred),3)\n    if name=="topic":rows["без пересечения"]["macro_f1_topic"]=round(f1_score(target.iloc[b],pred,labels=labels,average="macro",zero_division=0),3)\ntext_quality=pd.DataFrame(rows).T\nsent=new_model().fit(r.text,y);topic_model=new_model().fit(r.text,r.topic)','acc_sent=.943,acc_topic=.820,text_quality3×5,group592ID,финальные модели на2400'),
